   340|async function walkInspectableFiles(relDir: string, results: string[], max: number, projectRoot: string): Promise<void> {
   341|  if (results.length >= max) return;
   342|  const absDir = path.join(projectRoot, relDir);
   343|  let entries: string[];
   344|  try {
   345|    entries = await readdir(absDir);
   346|  } catch {
   347|    return;
   348|  }
   349|  for (const entry of entries) {
   350|    if (results.length >= max) return;
   351|    const relEntry = relDir ? `${relDir}/${entry}` : entry;
   352|    const absEntry = path.join(absDir, entry);
   353|    let info;
   354|    try {
