   372|function pickInspectionTargets(goal: string, availableFiles: string[]): string[] {
   373|  const alwaysInclude = [
   374|    'backend/services/ivx-autonomous-coder-pilot.ts',
   375|    'backend/services/ivx-senior-developer-worker.ts',
   376|    'backend/services/ivx-senior-developer-runtime.ts',
   377|    'backend/ivx-ai-runtime.ts',
   378|    'backend/api/ivx-owner-ai.ts',
   379|    'backend/hono.ts',
   380|    'render.yaml',
   381|    'package.json',
   382|  ].filter((f) => availableFiles.includes(f));
   383|
   384|  const words = Array.from(new Set(
   385|    goal.toLowerCase()
   386|      .replace(/[^a-z0-9\s]/g, ' ')
   387|      .split(/\s+/)
   388|      .filter((w) => w.length >= 4)
   389|      .filter((w) => !['that', 'this', 'with', 'from', 'have', 'please', 'change', 'deploy', 'anything', 'current', 'status', 'label', 'version'].includes(w)),
   390|  ));
   391|
   392|  const hintMatches = availableFiles
   393|    .filter((f) => words.some((w) => f.toLowerCase().includes(w)))
   394|    .slice(0, 15);
   395|
   396|  // Also include files whose CONTENT might contain the goal's significant terms.
   397|  // This is handled in the inspect phase by reading file previews.
   398|
   399|  return Array.from(new Set([...alwaysInclude, ...hintMatches])).slice(0, MAX_INSPECTED_FILES);
   400|}
