   402|async function readFilePreview(relPath: string, projectRoot: string): Promise<{ path: string; content: string; bytes: number } | null> {
   403|  try {
   404|    const absPath = path.join(projectRoot, relPath);
   405|    const content = await readFile(absPath, 'utf8');
   406|    const bytes = Buffer.byteLength(content, 'utf8');
   407|    // Send full content for small files so the LLM can copy oldText verbatim.
   408|    const preview = bytes <= FULL_CONTENT_THRESHOLD ? content : truncate(content, FILE_PREVIEW_CHARS);
   409|    return { path: relPath, content: preview, bytes };
   410|  } catch {
   411|    return null;
   412|  }
   413|}
