   416|
   417|/** Paths the autonomous coder is allowed to modify. */
   418|const ALLOWED_PATCH_PATHS = /^((?:backend|expo)\/[A-Za-z0-9_.\/-]+\.ts$|(?:backend|expo)\/[A-Za-z0-9_.\/-]+\.tsx$|expo\/[A-Za-z0-9_.\/-]+\.json$|expo\/[A-Za-z0-9_.\/-]+\.gradle$)/;
   419|
   420|function assertSafePatchPath(filePath: string): void {
   421|  if (filePath.includes('..') || filePath.startsWith('/')) {
   422|    throw new Error(`Unsafe patch path rejected: ${filePath}`);
   423|  }
   424|  if (!ALLOWED_PATCH_PATHS.test(filePath)) {
   425|    throw new Error(`Patch path outside allowed roots: ${filePath}. Only backend/*.ts, expo/*.ts(x), expo/*.json, expo/*.gradle are permitted.`);
   426|  }
