   429|async function applyPatchOperation(
   430|  op: IVXAutonomousCoderPatchOperation,
   431|  projectRoot: string,
   432|  fileWriter?: (relPath: string, content: string) => Promise<void>,
   433|  fileReader?: (relPath: string) => Promise<string>,
   434|): Promise<void> {
   435|  assertSafePatchPath(op.path);
   436|  const fullPath = path.join(projectRoot, op.path);
   437|  const write = fileWriter ?? (async (rel: string, content: string) => {
   438|    await mkdir(path.dirname(path.join(projectRoot, rel)), { recursive: true });
   439|    await writeFile(path.join(projectRoot, rel), content, 'utf8');
   440|  });
   441|  const read = fileReader ?? (async (rel: string) => readFile(path.join(projectRoot, rel), 'utf8'));
   442|  if (op.kind === 'create_file') {
   443|    const { existsSync } = await import('node:fs');
   444|    if (existsSync(fullPath)) {
   445|      throw new Error(`Create-file target already exists: ${op.path}`);
   446|    }
   447|    await write(op.path, op.newText);
   448|  } else {
   449|    const source = await read(op.path);
   450|    if (!source.includes(op.oldText)) {
   451|      throw new Error(`Patch oldText not found in ${op.path}; cannot apply safely.`);
   452|    }
   453|    const updated = source.replace(op.oldText, op.newText);
   454|    await write(op.path, updated);
   455|  }
   456|}
