   483|async function runCommand(cwd: string, command: string): Promise<IVXAutonomousCoderTestResult> {
   484|  const started = Date.now();
   485|  // Resolve the runtime: the Render container runs under node+tsx, not bun.
   486|  // `bun test` and `bun x tsc` fail with ENOENT on the production container, so
   487|  // we resolve the runtime via resolveRuntimeCommand and translate the command
   488|  // to its node-based equivalent when bun is not available.
   489|  const parts = command.split(/\s+/);
   490|  const requestedRuntime = parts[0] as 'bun' | 'bunx' | 'node' | 'npx';
   491|  const resolution = resolveRuntimeCommand(requestedRuntime);
