   578|
   579|function parseLLMPatchResponse(response: string): { rootCause: string; technicalPlan: string; operations: IVXAutonomousCoderPatchOperation[] } | null {
   580|  try {
   581|    // Strip markdown code fences if present (be aggressive — LLMs love fences)
   582|    const cleaned = response.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
   583|    // Some LLMs wrap the JSON in <json>...</json> or return prose before/after
   584|    const start = cleaned.indexOf('{');
   585|    const end = cleaned.lastIndexOf('}');
   586|    if (start < 0 || end < 0 || end <= start) return null;
   587|    let jsonStr = cleaned.slice(start, end + 1);
   588|    let parsed: { rootCause?: string; technicalPlan?: string; operations?: Array<{ path?: string; kind?: string; oldText?: string; newText?: string; reason?: string }> };
   589|    try {
   590|      parsed = JSON.parse(jsonStr);
   591|    } catch {
   592|      // Permissive fallback: strip trailing commas + fix smart quotes LLMs sometimes emit
   593|      const fixed = jsonStr
   594|        .replace(/,\s*([}\]])/g, '$1')
   595|        .replace(/[\u201c\u201d]/g, '"')
   596|        .replace(/[\u2018\u2019]/g, "'");
   597|      parsed = JSON.parse(fixed);
   598|    }
   599|    if (!Array.isArray(parsed.operations)) return null;
   600|    const operations: IVXAutonomousCoderPatchOperation[] = [];
   601|    for (const op of parsed.operations) {
   602|      if (typeof op.path !== 'string' || typeof op.kind !== 'string') continue;
   603|      if (op.kind !== 'replace_exact' && op.kind !== 'create_file') continue;
   604|      if (typeof op.oldText !== 'string' || typeof op.newText !== 'string') continue;
   605|      operations.push({
   606|        path: op.path,
   607|        kind: op.kind,
   608|        oldText: op.oldText,
   609|        newText: op.newText,
   610|        reason: typeof op.reason === 'string' ? op.reason : '',
   611|      });
   612|    }
   613|    // Empty operations is valid when the LLM signals "already satisfied" — return it so the loop exits cleanly (no phantom patch)
   614|    if (operations.length === 0) {
   615|      return {
   616|        rootCause: typeof parsed.rootCause === 'string' ? parsed.rootCause : 'no operations needed',
   617|        technicalPlan: typeof parsed.technicalPlan === 'string' ? parsed.technicalPlan : 'no change required',
   618|        operations: [],
   619|      };
   620|    }
   621|    return {
   622|      rootCause: typeof parsed.rootCause === 'string' ? parsed.rootCause : 'LLM-generated patch',
   623|      technicalPlan: typeof parsed.technicalPlan === 'string' ? parsed.technicalPlan : 'Replace exact text per operations',
   624|      operations,
   625|    };
   626|  } catch {
   627|    return null;
   628|  }
