   661|// ── DETERMINISTIC PILOT FALLBACK (Phase 3) ───────────────────────────────────
   662|//
   663|// For the CONTROLLED PILOT ONLY: when the goal explicitly asks to change the
   664|// pilot sentinel label AUTONOMOUS-CODER-PILOT-1 → AUTONOMOUS-CODER-PILOT-2,
   665|// the engine can apply the patch directly via an exact-replacement search across
   666|// safe source files, requiring EXACTLY ONE match or BLOCKED. This proves the
   667|// full loop end-to-end (inspect → patch → test → typecheck → commit) WITHOUT
   668|// depending on the LLM producing a valid patch — which was the root cause of the
   669|// stalled pilot (the LLM planning phase hung at RUNNING 10%).
   670|//
   671|// This fallback is LIMITED to the explicit pilot label change. It is NOT a
   672|// general uncontrolled editing mechanism. Any other goal still goes through the
   673|// LLM planning loop.
   674|
   675|// Generalized pilot fallback: handles ANY adjacent pilot label transition
   676|// (AUTONOMOUS-CODER-PILOT-N -> AUTONOMOUS-CODER-PILOT-(N+1)). The prior
   677|// implementation was hardcoded to PILOT-1 -> PILOT-2 only, which meant the
   678|// owner's next pilot goal (PILOT-2 -> PILOT-3) fell through to the LLM path
   679|// and hit the TS1470 false-positive in the scoped typecheck (see fix below).
   680|const PILOT_LABEL_PAIR_REGEX = /AUTONOMOUS-CODER-PILOT-(\d+)[\s\S]*?AUTONOMOUS-CODER-PILOT-(\d+)/i;
   681|const PILOT_LABEL_DEFINITION_REGEX_TEMPLATE = '(?:export\\s+const|const|export\\s+let|let)\\s+PILOT_LABEL\\s*=\\s*[\'"]AUTONOMOUS-CODER-PILOT-{N}[\'"]';
   682|
   683|/** Extracts the (from, to) label pair from a goal like
   684| * "change ... AUTONOMOUS-CODER-PILOT-2 ... to ... AUTONOMOUS-CODER-PILOT-3".
   685| * Returns null when the goal does not mention two distinct adjacent pilot labels. */
   686|function extractPilotLabelPair(goal: string): { fromLabel: string; toLabel: string; fromN: number; toN: number } | null {
   687|  const match = goal.match(PILOT_LABEL_PAIR_REGEX);
   688|  if (!match) return null;
   689|  const fromN = parseInt(match[1], 10);
   690|  const toN = parseInt(match[2], 10);
   691|  if (Number.isNaN(fromN) || Number.isNaN(toN)) return null;
   692|  // Only ADJACENT transitions (N -> N+1) are allowed — prevents arbitrary
   693|  // label overwrites and keeps the controlled-pilot invariant.
   694|  if (toN !== fromN + 1) return null;
   695|  return {
   696|    fromLabel: `AUTONOMOUS-CODER-PILOT-${fromN}`,
   697|    toLabel: `AUTONOMOUS-CODER-PILOT-${toN}`,
   698|    fromN,
   699|    toN,
   700|  };
