   709|/** Search all safe source files for the pilot sentinel DEFINITION (not mere
   710| * mentions). Returns the single matching file path or null (BLOCKED) when zero
   711| * or multiple definition matches are found. Test files (.test.ts/.test.tsx)
   712| * and this engine file are excluded from the scan so only the canonical sentinel
   713| * module counts. */
   714|async function findPilotSentinelFile(
   715|  fromLabel: string,
   716|  projectRoot: string,
   717|  fileReader?: (relPath: string) => Promise<string>,
   718|): Promise<string | null> {
   719|  const candidates: string[] = [];
   720|  const allFiles: string[] = [];
   721|  await walkInspectableFiles('backend', allFiles, 500, projectRoot);
   722|  await walkInspectableFiles('expo', allFiles, 500, projectRoot);
   723|  const read = fileReader ?? (async (rel: string) => readFile(path.join(projectRoot, rel), 'utf8'));
   724|  // Build a definition regex for the FROM label (e.g. AUTONOMOUS-CODER-PILOT-2).
   725|  const defPattern = new RegExp(PILOT_LABEL_DEFINITION_REGEX_TEMPLATE.replace('{N}', String(fromLabel.match(/\d+$/)?.[0] ?? '1')));
