   832|async function ensureBranchExists(
   833|  owner: string,
   834|  repo: string,
   835|  branch: string,
   836|  headers: Record<string, string>,
   837|): Promise<string> {
   838|  // Fast path: branch already exists — return its current HEAD SHA.
   839|  const refRes = await fetch(
   840|    `${GITHUB_API_BASE_URL}/repos/${owner}/${repo}/git/ref/heads/${encodeURIComponent(branch)}`,
   841|    { headers, signal: AbortSignal.timeout(10000) },
   842|  );
   843|  if (refRes.ok) {
   844|    const refData = await refRes.json() as { object?: { sha?: string } };
   845|    const existingSha = refData.object?.sha;
   846|    if (existingSha) return existingSha;
   847|  }
   848|  if (refRes.status !== 404) throw new Error(`GitHub branch ref lookup failed: ${refRes.status}`);
   849|  // Branch does not exist — create it from the default branch HEAD.
   850|  const defaultBranch = readEnv('GITHUB_DEFAULT_BRANCH') || GITHUB_DEFAULT_BRANCH;
   851|  const baseRefRes = await fetch(
   852|    `${GITHUB_API_BASE_URL}/repos/${owner}/${repo}/git/ref/heads/${encodeURIComponent(defaultBranch)}`,
   853|    { headers, signal: AbortSignal.timeout(10000) },
   854|  );
   855|  if (!baseRefRes.ok) throw new Error(`GitHub default branch ref lookup failed: ${baseRefRes.status}`);
   856|  const baseRefData = await baseRefRes.json() as { object?: { sha?: string } };
   857|  const baseSha = baseRefData.object?.sha;
   858|  if (!baseSha) throw new Error('GitHub default branch ref did not include a commit SHA.');
   859|  const createRefRes = await fetch(
   860|    `${GITHUB_API_BASE_URL}/repos/${owner}/${repo}/git/refs`,
   861|    {
   862|      method: 'POST',
   863|      headers,
   864|      body: JSON.stringify({ ref: `refs/heads/${branch}`, sha: baseSha }),
   865|      signal: AbortSignal.timeout(10000),
   866|    },
   867|  );
   868|  if (!createRefRes.ok && createRefRes.status !== 422) {
   869|    // 422 = branch already exists (race); treat as success.
   870|    throw new Error(`GitHub branch creation failed: ${createRefRes.status}`);
   871|  }
   872|  return baseSha;
   873|}
