   875|async function commitFilesViaGitDataApi(
   876|  filePaths: string[],
   877|  branch: string,
   878|): Promise<{ commitSha: string; commitUrl: string; branch: string }> {
   879|  const repoUrl = readEnv('GITHUB_REPO_URL');
   880|  const token = readEnv('GITHUB_TOKEN');
   881|  const repoInfo = parseGithubRepoUrl(repoUrl);
   882|  if (!repoInfo) throw new Error('GITHUB_REPO_URL is missing or invalid.');
   883|  if (!token) throw new Error('GITHUB_TOKEN is missing.');
   884|
   885|  const headers = {
   886|    Authorization: `Bearer ${token}`,
   887|    Accept: 'application/vnd.github+json',
   888|    'Content-Type': 'application/json',
   889|  };
   890|
   891|  // Ensure the target branch exists (create from default branch HEAD if missing).
   892|  const baseCommitSha = await ensureBranchExists(repoInfo.owner, repoInfo.repo, branch, headers);
   893|
   894|  // Get the base commit's tree
   895|  const commitRes = await fetch(
   896|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/commits/${encodeURIComponent(baseCommitSha)}`,
   897|    { headers, signal: AbortSignal.timeout(10000) },
   898|  );
   899|  if (!commitRes.ok) throw new Error(`GitHub base commit lookup failed: ${commitRes.status}`);
   900|  const commitData = await commitRes.json() as { tree?: { sha?: string } };
   901|  const baseTreeSha = commitData.tree?.sha;
   902|  if (!baseTreeSha) throw new Error('GitHub base commit did not include a tree SHA.');
   903|
   904|  // Create the new tree with the changed files
   905|  const tree = await Promise.all(filePaths.map(async (repoPath) => ({
   906|    path: repoPath,
   907|    mode: '100644' as const,
   908|    type: 'blob' as const,
   909|    content: await readFile(path.join(DEFAULT_PROJECT_ROOT, repoPath), 'utf8'),
   910|  })));
   911|
   912|  const treeRes = await fetch(
   913|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/trees`,
   914|    {
   915|      method: 'POST',
   916|      headers,
   917|      body: JSON.stringify({ base_tree: baseTreeSha, tree }),
   918|      signal: AbortSignal.timeout(15000),
   919|    },
   920|  );
   921|  if (!treeRes.ok) throw new Error(`GitHub tree creation failed: ${treeRes.status}`);
   922|  const treeData = await treeRes.json() as { sha?: string };
   923|  const newTreeSha = treeData.sha;
   924|  if (!newTreeSha) throw new Error('GitHub tree creation did not return a tree SHA.');
   925|
   926|  // Create the commit
   927|  const newCommitRes = await fetch(
   928|    `${GITHUB_API_BASE_URL}/repos/${repoInfo.owner}/${repoInfo.repo}/git/commits`,
   929|    {
   930|      method: 'POST',
   931|      headers,
   932|      body: JSON.stringify({
   933|        message: `IVX autonomous coder: ${new Date().toISOString()}`,
   934|        tree: newTreeSha,
   935|        parents: [baseCommitSha],
   936|      }),
   937|      signal: AbortSignal.timeout(15000),
